{
  "category_edits": [
    {
      "category": "sequence_modeling",
      "rationale": "Cap each target's causal context at min(original MAXLEN, 30), preserving chronological order and every existing training target. Compute bounded windows only for valid targets. Apply the same context limit during validation and generated prediction while preserving the GRU, readout, loss, optimizer, and routing.",
      "edits": [
        {
          "find": "MAXLEN        = int(os.environ.get("GRU4REC_MAXLEN", "128"))",
          "replace": "MAXLEN        = int(os.environ.get("GRU4REC_MAXLEN", "128"))
CONTEXT_MAXLEN = min(MAXLEN, 30)"
        },
        {
          "find": "    def __init__(self, itemnum: int, hidden_units: int = 128, num_layers: int = 1,
                 dropout_rate: float = 0.1):
        super().__init__()
        self.itemnum = itemnum
        self.hidden_units = hidden_units",
          "replace": "    def __init__(self, itemnum: int, hidden_units: int = 128, num_layers: int = 1,
                 dropout_rate: float = 0.1, context_maxlen: int = 30):
        super().__init__()
        self.itemnum = itemnum
        self.hidden_units = hidden_units
        self.context_maxlen = max(1, int(context_maxlen))"
        },
        {
          "find": "    def encode(self, seq: torch.Tensor) -> torch.Tensor:
        emb = self.dropout(self.item_emb(seq))",
          "replace": "    def encode(self, seq: torch.Tensor) -> torch.Tensor:
        seq = seq[:, -self.context_maxlen:]
        emb = self.dropout(self.item_emb(seq))"
        },
        {
          "find": "    def forward(self, seq: torch.Tensor, pos: torch.Tensor, neg: torch.Tensor):
        emb = self.dropout(self.item_emb(seq))
        out, _ = self.gru(emb)
        out = self.aggregate_states(out, seq)
        pos_scores = (out * self.item_emb(pos)).sum(dim=-1)
        neg_scores = (out * self.item_emb(neg)).sum(dim=-1)
        return pos_scores, neg_scores",
          "replace": "    def forward(self, seq: torch.Tensor, pos: torch.Tensor, neg: torch.Tensor):
        # Keep the original target set; truncate each target's input separately.
        valid = pos.ne(0)
        emb = self.dropout(self.item_emb(seq))
        width = self.context_maxlen
        seq_windows = torch.nn.functional.pad(seq, (width - 1, 0)).unfold(1, width, 1)
        emb_windows = torch.nn.functional.pad(
            emb, (0, 0, width - 1, 0)
        ).unfold(1, width, 1).transpose(-1, -2)
        pos_scores = emb.sum(dim=-1) * 0.0
        neg_scores = emb.sum(dim=-1) * 0.0
        if valid.any():
            window_seq = seq_windows[valid]
            window_emb = emb_windows[valid].contiguous()
            out, _ = self.gru(window_emb)
            states = self.aggregate_states(out, window_seq)[:, -1]
            pos_scores[valid] = (states * self.item_emb(pos[valid])).sum(dim=-1)
            neg_scores[valid] = (states * self.item_emb(neg[valid])).sum(dim=-1)
        return pos_scores, neg_scores"
        },
        {
          "find": "        dropout_rate=DROPOUT_RATE,
    ).to(device)",
          "replace": "        dropout_rate=DROPOUT_RATE,
        context_maxlen=CONTEXT_MAXLEN,
    ).to(device)"
        },
        {
          "find": "            "maxlen": MAXLEN,",
          "replace": "            "maxlen": CONTEXT_MAXLEN,
            "context_maxlen": CONTEXT_MAXLEN,"
        },
        {
          "find": "            dropout_rate=0.0,
        ).to(_device)",
          "replace": "            dropout_rate=0.0,
            context_maxlen=meta["context_maxlen"],
        ).to(_device)"
        }
      ]
    }
  ],
  "change_summary": "Bound training, validation, and prediction contexts to the latest 30 interactions while retaining all original training targets and one GRU checkpoint per category."
}
